{"implementation":"import math
def solve(case):
    matrix = case['matrix']
    idf = case['idf']
    vector = case['vector']
    rows = len(matrix)
    if rows == 0:
        raise ValueError("Empty matrix")
    cols = len(matrix[0])
    if cols != len(idf):
        raise ValueError("idf length mismatch")
    if rows != len(vector):
        raise ValueError("vector length mismatch")
    for r in matrix:
        if len(r) != cols:
            raise ValueError("Inconsistent row lengths")
    w = [[matrix[i][j] * idf[j] for j in range(cols)] for i in range(rows)]
    degree = [0.0] * rows
    for i in range(rows):
        s = sum(w[i][j]**2 for j in range(cols))
        degree[i] = s if s > 1e-12 else 1e-12
    v_scaled = [vector[i] / math.sqrt(degree[i]) for i in range(rows)]
    y = [0.0] * cols
    for j in range(cols):
        total = 0.0
        for i in range(rows):
            total += w[i][j] * v_scaled[i]
        y[j] = total
    z = [0.0] * rows
    for i in range(rows):
        total = 0.0
        for j in range(cols):
            total += w[i][j] * y[j]
        z[i] = total
    result = [z[i] / math.sqrt(degree[i]) for i in range(rows)]
    return {"degree": degree, "result": result}"}
